import { FiMapPin, FiMail, FiPhone, FiBriefcase } from 'react-icons/fi';

const ContactDetailsCards = () => {
  const contactItems = [
    { 
      icon: <FiMapPin className="w-5 h-5" />,
      label: "Location",
      detail: "Islamabad, Pakistan",
      color: "text-blue-500",
      bgColor: "bg-blue-50",
      hoverColor: "hover:bg-blue-100"
    },
    { 
      icon: <FiMail className="w-5 h-5" />,
      label: "Email",
      detail: "shahzaib@gmail.com",
      color: "text-red-500",
      bgColor: "bg-red-50",
      hoverColor: "hover:bg-red-100"
    },
    { 
      icon: <FiPhone className="w-5 h-5" />,
      label: "Phone",
      detail: "+92-XXX-XXXXXXX",
      color: "text-green-500",
      bgColor: "bg-green-50",
      hoverColor: "hover:bg-green-100"
    },
    { 
      icon: <FiBriefcase className="w-5 h-5" />,
      label: "Availability",
      detail: "Open to Freelance / Full-time",
      color: "text-purple-500",
      bgColor: "bg-purple-50",
      hoverColor: "hover:bg-purple-100"
    }
  ];

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
      <div className="text-center mb-10">
        <h2 className="text-3xl font-bold text-gray-800 dark:text-white">
          Get In <span className="bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">Touch</span>
        </h2>
        <p className="mt-3 text-lg text-gray-600 dark:text-gray-300 max-w-2xl mx-auto">
          Feel free to reach out for collaborations or just a friendly hello
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {contactItems.map((item, index) => (
          <div 
            key={index}
            className={`relative overflow-hidden rounded-xl p-6 ${item.bgColor} ${item.hoverColor} transition-all duration-300 group border border-gray-100 dark:border-gray-700 shadow-sm hover:shadow-md`}
          >
            {/* Icon with animated background */}
            <div className={`w-12 h-12 rounded-lg ${item.color} bg-white dark:bg-gray-800 flex items-center justify-center mb-4 shadow-inner group-hover:scale-110 transition-transform duration-300`}>
              {item.icon}
            </div>
            
            {/* Content */}
            <h3 className="text-lg font-semibold text-gray-800 dark:text-white mb-1">{item.label}</h3>
            <p className="text-gray-600 dark:text-gray-300">{item.detail}</p>
            
            {/* Animated border bottom */}
            <div className={`absolute bottom-0 left-0 h-1 w-0 ${item.color.replace('text', 'bg')} transition-all duration-500 group-hover:w-full`}></div>
            
            {/* Subtle hover effect */}
            <div className={`absolute inset-0 opacity-0 group-hover:opacity-10 ${item.color.replace('text', 'bg')} transition-opacity duration-300`}></div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ContactDetailsCards;