import { motion } from 'framer-motion';
import { FaGithub, FaLinkedinIn, FaTwitter, FaEnvelope, FaDribbble, FaBehance } from 'react-icons/fa';

const SocialLinks = () => {
  const socials = [
    {
      icon: <FaGithub className="text-xl" />,
      name: 'GitHub',
      url: 'https://github.com/yourusername',
      color: 'hover:text-gray-800 dark:hover:text-gray-200',
      bg: 'hover:bg-gray-100 dark:hover:bg-gray-800',
      border: 'border-gray-300 dark:border-gray-600'
    },
    {
      icon: <FaLinkedinIn className="text-xl" />,
      name: 'LinkedIn',
      url: 'https://linkedin.com/in/yourprofile',
      color: 'hover:text-[#0A66C2]',
      bg: 'hover:bg-[#0A66C2]/10',
      border: 'border-gray-300 dark:border-gray-600'
    },
    {
      icon: <FaTwitter className="text-xl" />,
      name: 'Twitter',
      url: 'https://twitter.com/yourhandle',
      color: 'hover:text-[#1DA1F2]',
      bg: 'hover:bg-[#1DA1F2]/10',
      border: 'border-gray-300 dark:border-gray-600'
    },
    {
      icon: <FaEnvelope className="text-xl" />,
      name: 'Email',
      url: 'mailto:youremail@example.com',
      color: 'hover:text-[#EA4335]',
      bg: 'hover:bg-[#EA4335]/10',
      border: 'border-gray-300 dark:border-gray-600'
    },
    {
      icon: <FaDribbble className="text-xl" />,
      name: 'Dribbble',
      url: 'https://dribbble.com/yourprofile',
      color: 'hover:text-[#EA4C89]',
      bg: 'hover:bg-[#EA4C89]/10',
      border: 'border-gray-300 dark:border-gray-600'
    },
    {
      icon: <FaBehance className="text-xl" />,
      name: 'Behance',
      url: 'https://behance.net/yourprofile',
      color: 'hover:text-[#1769FF]',
      bg: 'hover:bg-[#1769FF]/10',
      border: 'border-gray-300 dark:border-gray-600'
    }
  ];

  const container = {
    hidden: { opacity: 0 },
    show: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
        delayChildren: 0.3
      }
    }
  };

  const item = {
    hidden: { y: 20, opacity: 0 },
    show: {
      y: 0,
      opacity: 1,
      transition: {
        type: 'spring',
        stiffness: 100,
        damping: 10
      }
    }
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-12">
      <motion.div
        initial="hidden"
        whileInView="show"
        variants={container}
        viewport={{ once: true, margin: "-100px" }}
        className="flex flex-wrap justify-center gap-4 md:gap-6"
      >
        {socials.map((social, index) => (
          <motion.a
            key={index}
            variants={item}
            whileHover={{ y: -5 }}
            whileTap={{ scale: 0.95 }}
            href={social.url}
            target="_blank"
            rel="noopener noreferrer"
            className={`
              flex items-center gap-2 px-4 py-3 rounded-lg border
              transition-all duration-300 ease-in-out
              text-gray-700 dark:text-gray-300
              ${social.color} ${social.bg} ${social.border}
            `}
          >
            <span className="transition-transform duration-300 group-hover:scale-110">
              {social.icon}
            </span>
            <span className="text-sm font-medium">{social.name}</span>
          </motion.a>
        ))}
      </motion.div>
    </div>
  );
};

export default SocialLinks;