import { motion } from 'framer-motion';

const LocationMap = () => {
  return (
    <motion.div 
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6, ease: "easeOut" }}
      viewport={{ once: true, margin: "-50px" }}
      className="max-w-4xl mx-auto px-4 py-12"
    >
      <div className="text-center mb-8">
        <h3 className="text-2xl md:text-3xl font-bold text-gray-800 dark:text-white mb-2">
          My Location
        </h3>
        <p className="text-gray-600 dark:text-gray-300">
          Based in beautiful Karachi, Pakistan
        </p>
      </div>

      <motion.div
        whileHover={{ scale: 1.01 }}
        className="relative overflow-hidden rounded-xl shadow-xl border border-gray-200 dark:border-gray-700"
      >
        <div className="aspect-w-16 aspect-h-9 w-full h-64 md:h-80">
          <iframe
            src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3621.186965873899!2d67.0288473150001!3d24.81455798407172!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3eb33dbbdc1879a9%3A0xece5e7520eccc4e!2sKarachi%2C%20Pakistan!5e0!3m2!1sen!2s!4v1620000000000!5m2!1sen!2s"
            width="100%"
            height="100%"
            style={{ border: 0 }}
            allowFullScreen
            loading="lazy"
            referrerPolicy="no-referrer-when-downgrade"
            className="absolute inset-0 w-full h-full"
            aria-label="Google Maps location of Karachi, Pakistan"
          />
        </div>
        
        <div className="absolute inset-0 pointer-events-none">
          <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-50"></div>
        </div>
        
        <div className="absolute bottom-4 left-4 right-4">
          <motion.div 
            initial={{ y: 20, opacity: 0 }}
            whileInView={{ y: 0, opacity: 1 }}
            transition={{ delay: 0.4 }}
            viewport={{ once: true }}
            className="bg-white dark:bg-gray-800 inline-flex items-center px-4 py-2 rounded-lg shadow"
          >
            <svg className="w-5 h-5 mr-2 text-red-500" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M5.05 4.05a7 7 0 119.9 9.9L10 18.9l-4.95-4.95a7 7 0 010-9.9zM10 11a2 2 0 100-4 2 2 0 000 4z" clipRule="evenodd" />
            </svg>
            <span className="text-sm font-medium text-gray-800 dark:text-white">Karachi, Pakistan</span>
          </motion.div>
        </div>
      </motion.div>
    </motion.div>
  );
};

export default LocationMap;