import { useState, useRef } from 'react';
import { motion } from 'framer-motion';
import { FaPhone, FaEnvelope, FaLinkedin } from 'react-icons/fa';
import ContactDetailsCards from '../components/contact/ContactDetailsCards';
import SocialLinks from '../components/contact/SocialLinks';
import LocationMap from '../components/contact/LocationMap';
import CTA from '../components/contact/CTA';
import emailjs from 'emailjs-com';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const Contact = () => {
  const formRef = useRef();
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    subject: '',
    message: ''
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    emailjs
      .sendForm(
        'service_izjfz7z',
        'template_rvgneft',
        formRef.current,
        'T68OLA2iIK_jNhwDI'
      )
      .then(
        (result) => {
          toast.success('✅ Message sent successfully!', {
            position: 'top-right',
            autoClose: 3000,
            hideProgressBar: false,
            closeOnClick: true,
            pauseOnHover: true,
            draggable: true,
            theme: 'dark'
          });

          setFormData({
            name: '',
            email: '',
            subject: '',
            message: ''
          });
        },
        (error) => {
          console.error(error.text);
          toast.error('❌ Something went wrong. Please try again.', {
            position: 'top-right',
            autoClose: 3000,
            hideProgressBar: false,
            closeOnClick: true,
            pauseOnHover: true,
            draggable: true,
            theme: 'dark'
          });
        }
      );
  };

  return (
    <>
      <section
        id="contact"
        className="py-20 bg-gradient-to-br from-gray-900 to-gray-800 text-white"
      >
        <div className="container mx-auto px-4 max-w-6xl">
          {/* Header */}
          <motion.div
            initial={{ opacity: 0, y: 50 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            viewport={{ once: true }}
            className="text-center mb-16"
          >
            <h2 className="text-4xl font-bold mb-2 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-600">
              Get In Touch
            </h2>
            <p className="text-xl text-gray-300">Let's work together</p>
          </motion.div>

          {/* Contact Info + Form */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
            {/* Left: Info */}
            <motion.div
              initial={{ opacity: 0, x: -50 }}
              whileInView={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.5 }}
              viewport={{ once: true }}
              className="bg-gray-800 rounded-xl p-8 shadow-2xl"
            >
              <h3 className="text-2xl font-semibold mb-6 text-blue-400">Contact Information</h3>
              <p className="text-gray-300 mb-8">Feel free to reach out to me for any questions or opportunities.</p>

              <div className="space-y-6">
                <motion.div whileHover={{ x: 5 }} className="flex items-start">
                  <div className="bg-blue-600 p-3 rounded-full mr-4">
                    <FaPhone className="text-white text-lg" />
                  </div>
                  <div>
                    <h4 className="font-medium text-gray-300">Phone</h4>
                    <a href="tel:+923167855469" className="text-blue-400 hover:text-blue-300 transition-colors">
                      +92 316-7855469
                    </a>
                  </div>
                </motion.div>

                <motion.div whileHover={{ x: 5 }} className="flex items-start">
                  <div className="bg-purple-600 p-3 rounded-full mr-4">
                    <FaEnvelope className="text-white text-lg" />
                  </div>
                  <div>
                    <h4 className="font-medium text-gray-300">Email</h4>
                    <a
                      href="mailto:mrhahzaibabbasi@gmail.com"
                      className="text-blue-400 hover:text-blue-300 transition-colors break-all"
                    >
                      mrhahzaibabbasi@gmail.com
                    </a>
                  </div>
                </motion.div>

                <motion.div whileHover={{ x: 5 }} className="flex items-start">
                  <div className="bg-blue-500 p-3 rounded-full mr-4">
                    <FaLinkedin className="text-white text-lg" />
                  </div>
                  <div>
                    <h4 className="font-medium text-gray-300">LinkedIn</h4>
                    <a
                      href="https://linkedin.com/in/shahzaib-abbasi-"
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-blue-400 hover:text-blue-300 transition-colors break-all"
                    >
                      linkedin.com/in/shahzaib-abbasi-
                    </a>
                  </div>
                </motion.div>
              </div>
            </motion.div>

            {/* Right: Form */}
            <motion.div
              initial={{ opacity: 0, x: 50 }}
              whileInView={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.5 }}
              viewport={{ once: true }}
              className="bg-gray-800 rounded-xl p-8 shadow-2xl"
            >
              <h3 className="text-2xl font-semibold mb-6 text-purple-400">Send Me a Message</h3>

              <form ref={formRef} onSubmit={handleSubmit} className="space-y-6">
                <motion.div whileHover={{ scale: 1.01 }}>
                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    placeholder="Your Name"
                    required
                    className="w-full bg-gray-700 border border-gray-600 rounded-lg px-4 py-3 focus:outline-none focus:ring-2 focus:ring-purple-500 text-white placeholder-gray-400 transition-all"
                  />
                </motion.div>

                <motion.div whileHover={{ scale: 1.01 }}>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    placeholder="Your Email"
                    required
                    className="w-full bg-gray-700 border border-gray-600 rounded-lg px-4 py-3 focus:outline-none focus:ring-2 focus:ring-purple-500 text-white placeholder-gray-400 transition-all"
                  />
                </motion.div>

                <motion.div whileHover={{ scale: 1.01 }}>
                  <input
                    type="text"
                    name="subject"
                    value={formData.subject}
                    onChange={handleChange}
                    placeholder="Subject"
                    className="w-full bg-gray-700 border border-gray-600 rounded-lg px-4 py-3 focus:outline-none focus:ring-2 focus:ring-purple-500 text-white placeholder-gray-400 transition-all"
                  />
                </motion.div>

                <motion.div whileHover={{ scale: 1.01 }}>
                  <textarea
                    name="message"
                    value={formData.message}
                    onChange={handleChange}
                    placeholder="Your Message"
                    rows="5"
                    required
                    className="w-full bg-gray-700 border border-gray-600 rounded-lg px-4 py-3 focus:outline-none focus:ring-2 focus:ring-purple-500 text-white placeholder-gray-400 transition-all"
                  ></textarea>
                </motion.div>

                <motion.button
                  whileHover={{ scale: 1.05 }}
                  whileTap={{ scale: 0.95 }}
                  type="submit"
                  className="w-full bg-gradient-to-r from-purple-600 to-blue-500 text-white font-medium py-3 px-6 rounded-lg hover:from-purple-700 hover:to-blue-600 transition-all shadow-lg"
                >
                  Send Message
                </motion.button>
              </form>
            </motion.div>
          </div>
        </div>
      </section>

      <ContactDetailsCards />
      <SocialLinks />
      <LocationMap />
      <CTA />
      <ToastContainer />
    </>
  );
};

export default Contact;
