import { FiDownload, FiMail } from 'react-icons/fi';
import { motion } from 'framer-motion';

const CTA = () => {
  const handleDownload = () => {
    // Updated path to match your file structure
    const resumeUrl = '/assets/images/ShahzaibAbbasi-Resume.pdf';
    const link = document.createElement('a');
    link.href = resumeUrl;
    link.download = 'ShahzaibAbbasi-Resume.pdf'; // Make sure this matches your actual filename
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <section className="relative py-16 sm:py-24 bg-gradient-to-br from-indigo-50 to-blue-50 dark:from-gray-800 dark:to-gray-900 overflow-hidden">
      {/* Decorative elements */}
      <div className="absolute top-0 left-0 w-full h-full opacity-10">
        <div className="absolute top-20 left-20 w-40 h-40 rounded-full bg-blue-400 mix-blend-multiply filter blur-3xl"></div>
        <div className="absolute bottom-10 right-20 w-60 h-60 rounded-full bg-indigo-400 mix-blend-multiply filter blur-3xl"></div>
      </div>
      
      <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center">
          <motion.h2 
            className="text-3xl sm:text-4xl lg:text-5xl font-bold text-gray-900 dark:text-white mb-6"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            viewport={{ once: true }}
          >
            <span className="block">🤝 Let's build something </span>
            <span className="bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-transparent">amazing together!</span>
          </motion.h2>
          
          <motion.p 
            className="text-lg text-gray-600 dark:text-gray-300 max-w-2xl mx-auto mb-10"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.2 }}
            viewport={{ once: true }}
          >
            📧 I usually reply within 24 hours. Let's discuss your project or opportunity!
          </motion.p>
          
          <motion.div 
            className="flex flex-col sm:flex-row justify-center gap-4"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.4 }}
            viewport={{ once: true }}
          >
            <a
              href="mailto:shahzaib@gmail.com"
              className="flex items-center justify-center px-8 py-3.5 text-base font-medium text-white bg-gradient-to-r from-blue-600 to-indigo-600 rounded-lg shadow-lg hover:from-blue-700 hover:to-indigo-700 transition-all duration-300 transform hover:-translate-y-1 hover:shadow-xl"
            >
              <FiMail className="mr-2 h-5 w-5" />
              Contact Me
            </a>
            
            <button
              onClick={handleDownload}
              className="flex items-center justify-center px-8 py-3.5 text-base font-medium text-gray-800 dark:text-white bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-lg shadow-lg hover:bg-gray-50 dark:hover:bg-gray-600 transition-all duration-300 transform hover:-translate-y-1 hover:shadow-xl"
            >
              <FiDownload className="mr-2 h-5 w-5" />
              Download Resume
            </button>
          </motion.div>
        </div>
      </div>
    </section>
  );
};

export default CTA;